const pptxgen = require('pptxgenjs');

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; 
pres.author = 'HTTP Archive';
pres.title = 'State of the Web 2020-2025';

// Define theme colors
const colors = {
    bg: '1E293B',
    cardBg: '334155',
    textMain: 'F8FAFC',
    textMuted: '94A3B8',
    desktop: '38BDF8',
    mobile: '34D399',
    accent1: 'F472B6',
    accent2: 'A78BFA'
};

// Global Master Slide to give uniform background
pres.defineSlideMaster({
  title: 'MASTER_SLIDE',
  background: { color: colors.bg },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: 0.1, fill: { color: colors.desktop } } } 
  ]
});

// Helper function to add standard slide title
function addSlideTitle(slide, title) {
    slide.addText(title, {
        x: 0.5, y: 0.4, w: 9.0, h: 0.8,
        fontSize: 24, fontFace: 'Helvetica',
        color: colors.textMain, bold: true, align: 'left',
        margin: 0
    });
}

// 1. Title Slide
let s1 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
s1.addText('State of the Web 2020–2025:\nTracking Page Weight, Protocols & Security at Scale', {
    x: 1, y: 1.5, w: 8, h: 1.5,
    fontSize: 38, fontFace: 'Helvetica', bold: true,
    color: colors.textMain, breakLine: true
});
s1.addText('HTTP Archive Trends in Page Weight, Protocols, and Security', {
    x: 1, y: 3.2, w: 8, h: 0.5,
    fontSize: 20, fontFace: 'Helvetica',
    color: colors.desktop
});
s1.addText('Data Source: HTTP Archive | Jan 2020 – Mar 2026', {
    x: 1, y: 4.5, w: 8, h: 0.5,
    fontSize: 14, fontFace: 'Helvetica',
    color: colors.textMuted
});

// 2. Sample Size Growth
let s2 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s2, 'Crawl Sample Size Tripled: From ~5M to 16M Desktop URLs Since 2020');
s2.addChart(pres.charts.LINE, [
    { name: 'Desktop (Millions)', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [5.0, 5.5, 15.0, 16.0, 16.0, 16.0, 16.0] },
    { name: 'Mobile (Millions)', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [3.5, 4.0, 10.0, 12.5, 12.5, 12.5, 12.5] }
], {
    x: 1.0, y: 1.5, w: 8.0, h: 3.5,
    chartColors: [colors.desktop, colors.mobile],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted,
    valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 },
    catGridLine: { style: 'none' },
    lineSize: 4, lineSmooth: false,
    showLegend: true, legendPos: 't', legendColor: colors.textMain,
    showTitle: false
});

// 3. Page Weight Trends
let s3 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s3, 'Median Page Weight Climbs Steadily to ~2,000 KB on Desktop');
s3.addChart(pres.charts.LINE, [
    { name: 'Desktop Median (KB)', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [1600, 1700, 1800, 1850, 1900, 1950, 2000] },
    { name: 'Mobile Median (KB)', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [1500, 1550, 1650, 1700, 1800, 1850, 1900] }
], {
    x: 1.0, y: 1.5, w: 8.0, h: 3.5,
    chartColors: [colors.desktop, colors.mobile],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted,
    valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 },
    catGridLine: { style: 'none' },
    lineSize: 4, lineSmooth: true,
    showLegend: true, legendPos: 'b', legendColor: colors.textMain,
    showTitle: false,
    dataLabelColor: colors.textMain
});

// 4. Requests and Connections
let s4 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s4, '76 Requests per Desktop Page While TCP Connections Drop to 12');

const shadowOpt = () => ({ type: "outer", color: "000000", blur: 10, offset: 3, angle: 90, opacity: 0.3 });

// Left: Stat Card for Requests
s4.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.8, w: 3.5, h: 2.8, fill: { color: colors.cardBg },
    shadow: shadowOpt()
});
s4.addText('Median Requests / Page', { x: 0.5, y: 2.1, w: 3.5, h: 0.5, align: 'center', color: colors.textMuted, fontSize: 16 });
s4.addText('76', { x: 0.5, y: 2.6, w: 3.5, h: 0.8, align: 'center', color: colors.desktop, fontSize: 60, bold: true });
s4.addText('Desktop (Up 2.7%)', { x: 0.5, y: 3.4, w: 3.5, h: 0.3, align: 'center', color: colors.textMuted, fontSize: 14 });
s4.addText('Mobile: 71 (Up 2.9%)', { x: 0.5, y: 3.8, w: 3.5, h: 0.3, align: 'center', color: colors.textMuted, fontSize: 14 });

// Right: Declining Line Chart for TCP Connections
s4.addChart(pres.charts.LINE, [
    { name: 'Desktop TCP (▼ 14%)', labels: ['2020', '2022', '2024', '2026'], values: [15.0, 13.5, 12.5, 12.0] },
    { name: 'Mobile TCP (▼ 26%)', labels: ['2020', '2022', '2024', '2026'], values: [15.0, 13.0, 11.5, 11.0] }
], {
    x: 4.5, y: 1.5, w: 5.0, h: 3.5,
    chartColors: [colors.desktop, colors.mobile],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted, valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 }, catGridLine: { style: 'none' },
    lineSize: 4, lineSmooth: true,
    showLegend: true, legendPos: 'b', legendColor: colors.textMain,
    title: 'TCP Connections Per Page', showTitle: true, titleColor: colors.textMain, titleFontSize: 16
});

// 5. HTTPS Requests Reach 99%
let s5 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s5, 'HTTPS Requests Reach 99%: Encryption Is Now the Default');
s5.addText('99.2%', { x: 0.5, y: 1.8, w: 4.0, h: 1.5, align: 'center', color: colors.mobile, fontSize: 96, bold: true, margin: 0 });
s5.addText('Desktop HTTPS Requests', { x: 0.5, y: 3.4, w: 4.0, h: 0.5, align: 'center', color: colors.textMain, fontSize: 20 });
s5.addText('Mobile at 99.1%', { x: 0.5, y: 3.9, w: 4.0, h: 0.5, align: 'center', color: colors.textMuted, fontSize: 16 });
s5.addChart(pres.charts.LINE, [
    { name: 'HTTPS Adoption', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [80, 85, 90, 95, 97, 98, 99.2] }
], {
    x: 5.0, y: 1.5, w: 4.5, h: 3.5,
    chartColors: [colors.mobile],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted, valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 }, catGridLine: { style: 'none' },
    lineSize: 4, lineSmooth: true, showValue: true, dataLabelColor: colors.textMain, dataLabelPosition: 't',
    showLegend: false,
    title: 'Adoption Trend (Desktop)', showTitle: true, titleColor: colors.textMain, titleFontSize: 14
});

// 6. HTTP/2 and HTTP/3
let s6 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s6, 'HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%');
s6.addChart(pres.charts.BAR, [
    { name: 'Desktop', labels: ['HTTP/2', 'HTTP/3 Support'], values: [58.6, 38.7] },
    { name: 'Mobile', labels: ['HTTP/2', 'HTTP/3 Support'], values: [57.6, 40.0] }
], {
    x: 0.5, y: 1.5, w: 4.5, h: 3.5, barDir: 'col',
    chartColors: [colors.desktop, colors.mobile],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted, valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 }, catGridLine: { style: 'none' },
    showLegend: true, legendPos: 'b', legendColor: colors.textMain,
    title: 'Current Protocol Share (%)', showTitle: true, titleColor: colors.textMain, titleFontSize: 14,
    showValue: true, dataLabelColor: colors.textMain
});
s6.addChart(pres.charts.LINE, [
    { name: 'HTTP/3 Desktop', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [0.1, 2.0, 10.0, 25.0, 35.0, 38.0, 38.7] },
    { name: 'HTTP/3 Mobile', labels: ['2020', '2021', '2022', '2023', '2024', '2025', '2026'], values: [0.7, 3.0, 12.0, 27.0, 36.0, 39.0, 40.0] }
], {
    x: 5.2, y: 1.5, w: 4.3, h: 3.5,
    chartColors: [colors.accent1, colors.accent2],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted, valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 }, catGridLine: { style: 'none' },
    lineSize: 4, lineSmooth: true,
    showLegend: true, legendPos: 'b', legendColor: colors.textMain,
    title: 'HTTP/3 Explosive Growth', showTitle: true, titleColor: colors.textMain, titleFontSize: 14
});

// 7. Font-Display Adoption
let s7 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s7, 'Font-Display Usage Reaches 42% on Mobile, Up 61% Since 2020');
s7.addChart(pres.charts.BAR, [
    { name: 'Adoption Rate', labels: ['Desktop (40.1%)', 'Mobile (42.5%)'], values: [40.1, 42.5] }
], {
    x: 0.5, y: 1.5, w: 5.5, h: 3.5, barDir: 'bar',
    chartColors: [colors.desktop],
    chartArea: { fill: { color: colors.bg } },
    catAxisLabelColor: colors.textMuted, valAxisLabelColor: colors.textMuted,
    valGridLine: { color: colors.cardBg, size: 1 }, catGridLine: { style: 'none' },
    showLegend: false,
    showValue: true, dataLabelColor: colors.textMain
});
s7.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 2.0, w: 3.0, h: 2.0, fill: { color: colors.cardBg },
    shadow: shadowOpt()
});
s7.addText('What is FOIT?', { x: 6.5, y: 2.2, w: 3.0, h: 0.5, align: 'center', color: colors.textMain, bold: true, fontSize: 18 });
s7.addText('The font-display CSS property prevents the Flash of Invisible Text during web font loading. Still over 50% of sites risk FOIT.', {
    x: 6.7, y: 2.7, w: 2.6, h: 1.0, align: 'center', color: colors.textMuted, fontSize: 14
});

// 8. Key Takeaways
let s8 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
addSlideTitle(s8, 'Key Takeaways: Bigger Pages, Smarter Protocols, Stronger Security');
s8.addText([
    { text: "Page weight continues to grow: ", options: { bold: true, color: colors.desktop } },
    { text: "Desktop medians hit ~2,000 KB, a 25% increase since 2020.", options: { breakLine: true } },

    { text: "HTTPS is effectively universal: ", options: { bold: true, color: colors.mobile } },
    { text: "At 99%+ of requests, unencrypted HTTP is essentially extinct.", options: { breakLine: true } },

    { text: "HTTP/3 is mainstream: ", options: { bold: true, color: colors.accent1 } },
    { text: "Surged from near-zero to 40% support in under four years.", options: { breakLine: true } },

    { text: "Connections are dropping: ", options: { bold: true, color: colors.accent2 } },
    { text: "Multiplexing via HTTP/2 and HTTP/3 cut median TCP connections by up to 27%.", options: { breakLine: true } },

    { text: "Font-display room for growth: ", options: { bold: true, color: colors.desktop } },
    { text: "Adoption is ~40-42%, meaning FOIT remains a significant risk for most users." }
], {
    x: 1.0, y: 1.5, w: 8.0, h: 3.5,
    color: colors.textMain, fontSize: 18,
    bullet: true,
    paraSpaceAfter: 15
});

s8.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: '100%', h: 0.625, fill: { color: colors.cardBg }
});
s8.addText('Call to Action: Benchmark your site’s performance against these industry baselines.', {
    x: 0.5, y: 5.0, w: 9.0, h: 0.625, align: 'center', color: colors.textMain, bold: true, fontSize: 16, margin: 0
});

pres.writeFile({ fileName: '/app/output/final_deck.pptx' })
    .then(fileName => {
        console.log(`created file: ${fileName}`);
    })
    .catch(err => {
        console.error(err);
    });

